create or replace function public.group_invite_notification_trigger() returns trigger language plpgsql security definer set search_path=public as $$ declare group_name text; actor_name text; begin select name into group_name from public.chat_groups where id=new.group_id; select coalesce(display_name,username,'MatchUp player') into actor_name from public.profiles where id=new.invited_by; if tg_op='INSERT' then insert into public.notifications(recipient_id,kind,payload) values(new.invited_user_id,'group_invitation',jsonb_build_object('actor_id',new.invited_by,'message',actor_name||' invited you to join '||coalesce(group_name,'a group')||'.','entity_type','group','entity_id',new.group_id::text)); elsif tg_op='UPDATE' and old.status='pending' and new.status in ('accepted','declined') then insert into public.notifications(recipient_id,kind,payload) values(new.invited_by,case when new.status='accepted' then 'group_invitation_accepted' else 'group_invitation_declined' end,jsonb_build_object('actor_id',new.invited_user_id,'message',coalesce((select display_name from public.profiles where id=new.invited_user_id),'MatchUp player')||case when new.status='accepted' then ' accepted your group invitation.' else ' declined your group invitation.' end,'entity_type','group','entity_id',new.group_id::text)); end if; return new; end; $$;
drop trigger if exists chat_group_invites_notifications on public.chat_group_invites;
create trigger chat_group_invites_notifications after insert or update on public.chat_group_invites for each row execute function public.group_invite_notification_trigger();
